class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def solve(self, head: ListNode) -> ListNode:
        if not head or not head.next:
            return head

        even_head = head.next
        even = even_head
        odd = head

        while even and even.next:
            odd.next = even.next
            odd = odd.next
            even.next = odd.next
            even = even.next

        odd.next = even_head
        return head
